// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testRegression_property() public {
        address recipient = address(0xBEEF);
        vm.deal(address(c), 200 wei);

        vm.prank(recipient);
        c.getFirstWithdrawalBonus(recipient);

        bool ok;
        try c.getFirstWithdrawalBonus(recipient) { ok = true; } catch { ok = false; }

        assertTrue(ok == false, "Second call should revert due to claimedBonus guard");
    }
}
